# Antiquity polity profiles, part 1: Persia, Greeks, Macedon, Hellenistic kingdoms
P = []
def add(**k): P.append(k)

add(id="achaemenid", name="Achaemenid Persia", type="empire", yearsActive="c. 550–330 BC",
 summary="The first Persian empire, founded by Cyrus the Great, which ruled from the Aegean to the Indus and reached into Europe in Thrace before Alexander destroyed it.",
 description="Cyrus II united the Medes and Persians around 550 BC, took Lydia (546) and Babylon (539), and his successors added Egypt and the Indus valley. Darius I (522–486) organised the empire into satrapies linked by the Royal Road and a standard gold coinage, the daric. In Europe the Persians held Thrace and received the submission of Macedon around 512–492 BC. The Ionian Revolt (499–493) drew them into war with Athens and Sparta, and defeats at Marathon (490), Salamis (480) and Plataea (479) ended their advance into Greece.",
 conflicts="Darius's Scythian campaign crossed the Danube around 513 BC. The Ionian Revolt led to the Persian Wars: Marathon (490), Thermopylae and Salamis (480), Plataea and Mycale (479). Alexander destroyed the empire at the Granicus (334), Issus (333) and Gaugamela (331).",
 leaders="Cyrus the Great (c. 559–530), Darius I (522–486) and Xerxes I (486–465) built the empire; Darius III (336–330) was the last king, murdered by his own satrap Bessus.",
 religion="The kings honoured Ahura Mazda, the wise lord of Zoroastrian tradition, while tolerating local cults; Cyrus allowed the Jews to return from Babylon and rebuild the Temple.",
 culture="Persepolis, begun by Darius, was the ceremonial capital. Aramaic served as the imperial administrative language, and Persian nobles were raised to 'ride, shoot the bow and speak the truth' (Herodotus).",
 literature="Darius's Behistun inscription, in Old Persian, Elamite and Babylonian, tells how he took the throne; the Greek view of Persia comes from Herodotus and Aeschylus's The Persians (472 BC).",
 art="The Apadana reliefs at Persepolis show delegations from twenty-three nations bringing tribute, in a court style that mixes Assyrian, Egyptian and Greek elements.",
 ideas="The Cyrus Cylinder presents the king as restorer of local gods and peoples; Persian rule set the model of a multi-ethnic empire held together by roads, tribute and tolerance.",
 science="Persian engineers built qanats (underground irrigation channels), a canal from the Nile to the Red Sea and the Royal Road with relay stations from Sardis to Susa.",
 story=[{"title":"Xerxes whips the sea","text":"When a storm destroyed his first bridge of boats across the Hellespont in 480 BC, Xerxes, says Herodotus, had the sea given three hundred lashes and a pair of fetters thrown into it. A second bridge held, and his army crossed into Europe."}],
 sources="Encyclopaedia Britannica, 'Achaemenian dynasty'; P. Briant, From Cyrus to Alexander (2002); Herodotus, Histories.",
 images=[("Persepolis Apadana relief tribute","Tribute bearers on the Apadana stairway at Persepolis","art"),
         ("Daric coin Achaemenid gold","Gold daric showing the Persian king as an archer","culture")])

add(id="greek-poleis", name="Greek city-states", type="city-states", yearsActive="c. 800–146 BC (independent poleis)",
 summary="The hundreds of self-governing Greek cities of the Aegean, southern Italy, Sicily and the western Mediterranean, including Athens, Sparta, Corinth, Syracuse and Massalia.",
 description="The polis, a city with its farmland governed by its citizens, was the basic unit of Greek life from the eighth century BC. Colonies spread Greek cities from Marseille (Massalia) and Emporion in the west to the Black Sea. In 500 BC Athens had just become a democracy under Cleisthenes, Sparta led the Peloponnesian League, and Syracuse dominated Sicily. After defeating Persia, Athens built an Aegean empire, and its rivalry with Sparta led to the Peloponnesian War (431–404). Philip II of Macedon defeated Athens and Thebes at Chaeronea in 338 BC, ending the cities' independence in practice.",
 conflicts="The Persian Wars (490–479), the Peloponnesian War (431–404) and the Corinthian War (395–387) were the great Greek wars; in the west Syracuse fought Carthage and Athens' disastrous Sicilian Expedition (415–413) failed before its walls.",
 leaders="Cleisthenes founded Athenian democracy (508/7 BC); Themistocles built the fleet that won at Salamis; Pericles led Athens at its height (c. 461–429); Gelon and Dionysius I ruled Syracuse as tyrants.",
 religion="Each city honoured the Olympian gods with its own patron, such as Athena at Athens; Panhellenic sanctuaries at Olympia and Delphi, the Olympic Games and the Delphic oracle bound the Greeks together.",
 culture="Citizens met in the agora and assembly, trained in the gymnasium and fought as hoplites in the phalanx; Athenian drama festivals and the Panathenaia were civic religious events.",
 literature="Aeschylus, Sophocles and Euripides wrote tragedy and Aristophanes comedy; Herodotus and Thucydides invented history; Pindar wrote victory odes for athletes.",
 art="The Parthenon (447–432 BC), with sculpture directed by Phidias, defined the classical style; red-figure vase painting and bronze statues such as the Riace warriors show the period's skill.",
 ideas="Socrates, Plato and Aristotle founded Western philosophy in Athens; the Ionian thinkers Thales and Heraclitus had already sought natural explanations of the world.",
 science="Hippocrates of Kos separated medicine from religion; Pythagoras, Euclid and later Archimedes of Syracuse laid the foundations of mathematics and mechanics.",
 story=[{"title":"Ostracism","text":"Once a year Athenians could vote to exile a too-powerful citizen for ten years by scratching his name on a pottery sherd, an ostrakon. Thousands of these sherds have been found, some with the same name in the same handwriting, ballots prepared in advance."}],
 sources="Encyclopaedia Britannica, 'ancient Greek civilization'; M. H. Hansen, Polis (2006); Thucydides, History of the Peloponnesian War.",
 images=[("The Parthenon in Athens.jpg","The Parthenon on the Athenian Acropolis (447–432 BC)","art"),
         ("Athenian owl tetradrachm","Athenian silver tetradrachm with the owl of Athena","culture")])

add(id="alexander-empire", name="Empire of Alexander the Great", type="empire", yearsActive="336–323 BC (divided by 301 BC)",
 summary="The empire won by Alexander III of Macedon, who conquered the Persian Empire from Egypt to the Indus between 334 and 325 BC and died in Babylon in 323 BC.",
 description="Philip II made Macedon the leading power in Greece and planned a war on Persia; after his murder in 336 BC his son Alexander carried it out. Alexander crossed into Asia in 334, won at the Granicus, Issus and Gaugamela, founded Alexandria in Egypt and burned Persepolis. He pushed on through Bactria to the Indus before his army refused to go further. When he died in Babylon in June 323 BC, aged 32, his generals divided the empire, and the wars of the Successors (Diadochi) produced the Hellenistic kingdoms.",
 conflicts="Granicus (334), Issus (333), the siege of Tyre (332), Gaugamela (331) and the Hydaspes against King Porus in India (326) were Alexander's major battles; Antipater crushed a Spartan revolt at Megalopolis (331).",
 leaders="Alexander III (336–323) ruled with Antipater as regent in Macedon; Perdiccas, Ptolemy, Seleucus, Antigonus and Lysimachus became the Successors.",
 religion="Alexander sacrificed to Greek gods and local ones alike; at the oracle of Ammon at Siwa he was greeted as son of the god, and he later asked the Greek cities to honour him as divine.",
 culture="Alexander adopted Persian court dress and proskynesis (prostration), married the Bactrian Roxane and held mass Greek-Persian weddings at Susa in 324 BC.",
 literature="Accounts by his companions Ptolemy and Aristobulus are lost; we read Alexander through Arrian, Plutarch and Curtius Rufus, writing centuries later. The Alexander Romance turned him into a legend from Iceland to Ethiopia.",
 art="Lysippos was his official sculptor and Apelles his painter; the Alexander Mosaic from Pompeii copies a painting of his battle with Darius.",
 ideas="Aristotle had been Alexander's tutor; the conquests spread Greek language and cities across the Near East and opened the Hellenistic age.",
 science="Surveyors (bematists) paced out his routes, and his expedition brought back knowledge of the plants, animals and geography of Asia.",
 story=[{"title":"The Gordian knot","text":"At Gordion in 333 BC Alexander was shown an ox-cart tied with a knot that, legend said, only the future ruler of Asia could undo. Unable to find the ends, he cut through it with his sword (or, in another version, pulled out the pin of the yoke)."}],
 sources="Encyclopaedia Britannica, 'Alexander the Great'; A. B. Bosworth, Conquest and Empire (1988); Arrian, Anabasis of Alexander.",
 images=[("Alexander the Great mosaic.jpg","Alexander at the battle of Issus, detail of the Alexander Mosaic from Pompeii","leader"),
         ("Alexander tetradrachm Herakles","Silver tetradrachm of Alexander with Herakles in a lion-skin","culture")])

add(id="antigonid-macedon", name="Antigonid Macedon and the Hellenic League", type="kingdom", yearsActive="c. 277–168 BC",
 summary="The Hellenistic kingdom of Macedon under the Antigonid dynasty, which dominated mainland Greece through the Hellenic League until Rome defeated it at Pydna in 168 BC.",
 description="After decades of wars among Alexander's successors, Antigonus II Gonatas secured the Macedonian throne in 277 BC by defeating invading Gauls. His successors controlled Greece through garrisons at Corinth, Chalcis and Demetrias, the 'fetters of Greece'. Philip V revived the Hellenic League in 224 BC and allied with Hannibal in 215, which brought Rome east. Rome defeated Philip at Cynoscephalae (197), and his son Perseus at Pydna (168), after which Macedon was split into four republics and became a Roman province in 146 BC.",
 conflicts="The Chremonidean War (267–261) against Athens and Sparta; the Social War against the Aetolian League (220–217); the four Macedonian Wars with Rome (214–148), lost at Cynoscephalae and Pydna.",
 leaders="Antigonus II Gonatas (277–239), Antigonus III Doson (229–221), Philip V (221–179) and Perseus (179–168), the last king, who died a prisoner in Italy.",
 religion="The kings honoured Zeus and Herakles, ancestor of the Macedonian royal house; Delos and Delphi received royal dedications.",
 culture="Pella was the royal capital, with pebble and later tessellated mosaics in its palaces and houses; Macedonian nobles served as Companions of the king.",
 literature="Polybius, who saw Macedon's fall, is our main source; the Stoic philosopher Persaeus served at Antigonus Gonatas's court.",
 art="The royal tombs at Vergina (Aigai), with wall paintings and gold larnakes, show Macedonian court art; the Winged Victory of Samothrace was probably a naval dedication of this era.",
 ideas="Antigonus Gonatas, a pupil of Zeno, described kingship as 'glorious servitude'; the Achaean and Aetolian Leagues experimented with federal government.",
 science="Hellenistic siege engineering and warships, such as the giant 'sixteens' of Demetrius, were developed in these wars.",
 story=[{"title":"The line in the sand","text":"After Pydna, Rome's power was such that in 168 BC the envoy Popillius Laenas met the Seleucid king Antiochus IV outside Alexandria, drew a circle around him in the sand and told him to decide before stepping out of it whether he would leave Egypt. Antiochus left."}],
 sources="Encyclopaedia Britannica, 'Macedonia: Hellenistic period'; Polybius, Histories; F. W. Walbank, The Hellenistic World (1981).",
 images=[("Philip V of Macedon tetradrachm","Silver tetradrachm of Philip V of Macedon","leader"),
         ("Vergina royal tombs museum","The royal tombs of Aigai at Vergina","art")])

add(id="seleucid", name="Seleucid Empire", type="kingdom", yearsActive="312–63 BC",
 summary="The largest of the Hellenistic kingdoms, founded by Alexander's general Seleucus I, which ruled from Anatolia and Syria to Iran and was steadily reduced by Rome and Parthia.",
 description="Seleucus I took Babylon in 312 BC and won most of Alexander's Asian empire at Ipsus (301). His dynasty founded Greek cities such as Antioch, Seleucia on the Tigris and Laodicea, which spread Greek culture across the Near East. Antiochus III restored the empire in a great eastern expedition but was defeated by Rome at Magnesia (190 BC) and lost Asia Minor west of the Taurus by the Peace of Apamea. Parthia took Iran and Mesopotamia in the 140s, and Pompey turned the remnant in Syria into a Roman province in 63 BC.",
 conflicts="Six Syrian Wars with Ptolemaic Egypt over Coele-Syria; the Roman–Seleucid War (192–188) ending at Magnesia; the Maccabean revolt in Judea (167–160); wars with Parthia.",
 leaders="Seleucus I Nicator (305–281), Antiochus I (281–261), Antiochus III the Great (222–187) and Antiochus IV Epiphanes (175–164).",
 religion="Kings were worshipped in a ruler cult and patronised Apollo, their claimed ancestor, as well as Babylonian temples; Antiochus IV's attempt to impose Greek cult in Jerusalem provoked the Maccabean revolt.",
 culture="Greek settlers lived in new cities with gymnasia and theatres alongside Babylonian, Aramaic and Iranian populations.",
 literature="The Babylonian priest Berossus wrote a history of Babylon in Greek for Antiochus I; the Books of Maccabees record the Jewish view of Seleucid rule.",
 art="Seleucid coin portraits are among the finest of Hellenistic art; Antioch's mosaics and the Tyche of Antioch statue were widely copied.",
 ideas="The Seleucid era, counted from 312 BC, was the first continuous dating system and was used in the Near East for over a thousand years.",
 science="Babylonian astronomers under the Seleucids kept systematic records and produced mathematical predictions of planetary positions.",
 story=[{"title":"War elephants","text":"Seleucus I traded the eastern provinces to the Indian king Chandragupta Maurya for 500 war elephants. They helped win the battle of Ipsus in 301 BC, and an elephant became a Seleucid emblem on coins."}],
 sources="Encyclopaedia Britannica, 'Seleucid kingdom'; S. Sherwin-White and A. Kuhrt, From Samarkhand to Sardis (1993).",
 images=[("Antiochus III the Great bust Louvre","Portrait of Antiochus III the Great","leader"),
         ("Seleucus I tetradrachm elephant","Silver tetradrachm of Seleucus I","culture")])

add(id="ptolemaic", name="Ptolemaic Kingdom", type="kingdom", yearsActive="305–30 BC",
 summary="The Macedonian dynasty that ruled Egypt from Alexandria for three centuries, also holding Cyprus and, at times, Aegean islands and Cyrenaica, until Cleopatra VII's defeat by Octavian.",
 description="Ptolemy I, one of Alexander's generals, took Egypt after 323 BC and declared himself king in 305. His dynasty ruled as pharaohs to Egyptians and as Hellenistic kings to Greeks, with a capital at Alexandria. Its navy controlled Cyprus and Aegean bases in the third century BC. Dynastic feuds and Roman pressure weakened the kingdom, and after Antony and Cleopatra lost at Actium in 31 BC, Egypt became a Roman province in 30 BC.",
 conflicts="The Syrian Wars against the Seleucids; the battle of Raphia (217 BC), won with native Egyptian troops; Actium (31 BC).",
 leaders="Ptolemy I Soter (305–282), Ptolemy II Philadelphus (282–246) and Cleopatra VII (51–30), the last ruler.",
 religion="The god Serapis combined Greek and Egyptian features; the kings built Egyptian temples at Edfu and Dendera and were worshipped as gods.",
 culture="Alexandria, with its lighthouse (the Pharos) and royal quarter, was the largest Greek city of its age.",
 literature="The Library of Alexandria gathered Greek literature; Callimachus, Theocritus and Apollonius of Rhodes wrote there, and the Hebrew Bible was translated into Greek as the Septuagint.",
 art="Royal portraits combined Greek realism with Egyptian conventions; the Rosetta Stone (196 BC) records a decree in three scripts.",
 ideas="The Museum of Alexandria, a state-funded research institute, was a model for later academies.",
 science="Euclid wrote the Elements, Eratosthenes measured the Earth's circumference and Herophilus dissected human bodies in Alexandria.",
 story=[{"title":"Measuring the Earth","text":"Eratosthenes heard that at noon on the summer solstice the sun shone straight down a well at Syene, while at Alexandria it cast a shadow of about 7 degrees. From this angle and the distance between the cities he worked out the Earth's circumference with remarkable accuracy."}],
 sources="Encyclopaedia Britannica, 'Ptolemaic dynasty'; G. Hölbl, A History of the Ptolemaic Empire (2001).",
 images=[("Rosetta Stone.JPG","The Rosetta Stone, a Ptolemaic decree of 196 BC in hieroglyphic, Demotic and Greek","culture"),
         ("Ptolemy I Soter coin","Coin portrait of Ptolemy I Soter","leader")])

add(id="pergamon", name="Kingdom of Pergamon", type="kingdom", yearsActive="282–133 BC",
 summary="The Attalid kingdom of north-western Anatolia, a Roman ally whose capital Pergamon rivalled Alexandria in culture, bequeathed to Rome in 133 BC.",
 description="Philetaerus, guardian of Lysimachus's treasure at Pergamon, made himself independent in 282 BC. Attalus I took the title of king after defeating the Galatians, and the Attalids sided with Rome against Macedon and the Seleucids. After Magnesia (190 BC) Rome gave them most of western Asia Minor. Attalus III left the kingdom to Rome in his will, and it became the province of Asia.",
 conflicts="Wars against the Galatians (Celts who had crossed into Anatolia in 278 BC); alliance with Rome in the Macedonian Wars and against Antiochus III; the revolt of Aristonicus after 133 BC.",
 leaders="Philetaerus (282–263), Attalus I (241–197), Eumenes II (197–159) and Attalus III (138–133).",
 religion="Athena Nikephoros was the city's patron; the Great Altar honoured Zeus and Athena, and the Asclepieion was a famous healing sanctuary.",
 culture="Pergamon was built in terraces up its acropolis, with a theatre cut into the steep hillside.",
 literature="Its library was second only to Alexandria's; Crates of Mallos led its grammarians.",
 art="The Great Altar's frieze of gods fighting giants and the Dying Gaul statue are masterpieces of the Pergamene 'baroque' style.",
 ideas="Pergamon's scholars favoured allegorical reading of Homer, against the Alexandrians' textual criticism.",
 science="According to Pliny, parchment (pergamenum) was developed there when Egypt stopped exporting papyrus; the physician Galen was born at Pergamon in AD 129.",
 story=[{"title":"The Dying Gaul","text":"To celebrate victory over the Galatians, Attalus I set up bronze statues of defeated Celts. A Roman marble copy, the Dying Gaul, shows a wounded warrior with a torc around his neck sinking to the ground."}],
 sources="Encyclopaedia Britannica, 'Pergamum'; E. V. Hansen, The Attalids of Pergamon (2nd ed. 1971).",
 images=[("Pergamonaltar","The Great Altar of Pergamon, now in Berlin","art"),
         ("Dying Gaul Capitoline","The Dying Gaul, Roman copy of a Pergamene bronze","art")])

add(id="anatolian-kingdoms", name="Hellenistic Anatolian kingdoms", type="kingdoms", yearsActive="c. 330–17 AD (Cappadocia annexed AD 17)",
 nameByTick={"-323": "Cappadocia"},
 summary="The native and Hellenised kingdoms of Anatolia, including Cappadocia, Pontus, Bithynia and Galatia, which emerged from the Persian satrapies after Alexander and were absorbed by Rome.",
 description="Alexander bypassed northern and eastern Anatolia, where Persian-descended dynasts kept power. Cappadocia under Ariarathes resisted the Successors, and Pontus, Bithynia and the Celtic Galatians established kingdoms in the third century BC. Mithridates VI of Pontus (120–63 BC) built a Black Sea empire and fought Rome in three wars before Pompey defeated him. Rome turned the kingdoms into client states and then provinces: Bithynia in 74 BC, Galatia in 25 BC and Cappadocia in AD 17.",
 conflicts="Wars among the kingdoms and with the Seleucids; the Mithridatic Wars (89–63 BC), including the massacre of Romans in Asia in 88 BC.",
 leaders="Ariarathes I of Cappadocia; Nicomedes I of Bithynia, who invited the Galatians across the Bosporus; Mithridates VI Eupator of Pontus.",
 religion="Iranian fire cults and the great temple-states of Comana coexisted with Greek gods; the Galatians kept Celtic gods and a council at the sacred oak grove of Drunemeton.",
 culture="Persian, Greek, Anatolian and Celtic traditions mixed; Greek became the language of the courts.",
 literature="Strabo, born at Amaseia in Pontus around 64 BC, described the region in his Geography.",
 art="Royal coin portraits, especially those of Mithridates VI in the style of Alexander, are the best-known art of these kingdoms.",
 ideas="Mithridates presented himself as defender of the Greeks against Rome.",
 science="Mithridates was said to have taken small doses of poison daily to make himself immune, and his name gave us 'mithridatism'.",
 story=[{"title":"The poison king","text":"Defeated by Pompey and betrayed by his son, Mithridates VI tried to poison himself in 63 BC, but after years of taking antidotes the poison failed. He had a bodyguard kill him with a sword."}],
 sources="Encyclopaedia Britannica, 'Cappadocia', 'Pontus', 'Mithradates VI Eupator'; A. Mayor, The Poison King (2010).",
 images=[("Mithridates VI tetradrachm","Coin portrait of Mithridates VI Eupator of Pontus","leader")])

add(id="bosporan", name="Bosporan Kingdom", type="kingdom", yearsActive="c. 438 BC–AD 4th century",
 summary="The Greek kingdom on both sides of the Kerch Strait in Crimea and the Taman peninsula, which exported Scythian grain to Athens and later became a Roman client state.",
 description="Greek colonies such as Panticapaeum (Kerch) and Phanagoria united under the Spartocid dynasty around 438 BC. They traded grain, fish and slaves from the steppe to Athens in return for wine, oil and fine goods, and ruled over Scythian and Maeotian neighbours. In 108 BC the last Spartocid handed the kingdom to Mithridates VI of Pontus. Under Rome it was a client kingdom, often ruled by Sarmatian-descended kings, until the Goths and Huns overran it in the third and fourth centuries AD.",
 conflicts="Wars with the Scythians and Sarmatians; the civil war of 310–309 BC among the sons of Paerisades I; Pharnaces II's defeat by Caesar at Zela in 47 BC.",
 leaders="Spartocus I founded the dynasty; Leucon I (389–349) and Paerisades I made it a great grain exporter; Asander and Queen Dynamis ruled under Augustus.",
 religion="Greek gods were worshipped alongside Scythian and Sarmatian cults; Jewish communities and later Christians are attested in Panticapaeum.",
 culture="Greek city life on the edge of the steppe, with nomad aristocrats buried in rich kurgans nearby.",
 literature="Demosthenes praised Leucon for supplying grain to Athens; inscriptions record its kings and manumissions.",
 art="Gold work from kurgans such as Kul-Oba, made by Greek craftsmen in Scythian taste, is now in the Hermitage.",
 ideas="It was an early example of a Greek-barbarian state in which Greek kings ruled native peoples.",
 science="Its grain exports were essential to Athens' food supply in the fourth century BC.",
 story=[{"title":"Grain for Athens","text":"In the 350s BC Athens imported about 400,000 medimnoi of grain a year from the Bosporus, roughly half its needs. The Athenians gave Leucon and his sons citizenship and exempted their ships from harbour dues."}],
 sources="Encyclopaedia Britannica, 'Bosporus, Kingdom of the'; D. Braund (ed.), Scythians and Greeks (2005).",
 images=[("Kul-Oba","Gold work from the Kul-Oba kurgan near Kerch","art")])
